fn paethPredictor(
    mut a: c_uchar,
    mut b: c_uchar,
    mut c: c_uchar,
) -> c_uchar {
    let ai = a as c_int;
    let bi = b as c_int;
    let ci = c as c_int;

    let mut pa = bi - ci;
    if pa < 0 {
        pa = -pa;
    }

    let mut pb = ai - ci;
    if pb < 0 {
        pb = -pb;
    }

    let mut pc = ai + bi - ci - ci;
    if pc < 0 {
        pc = -pc;
    }

    if pb < pa {
        a = b;
        pa = pb;
    }

    if pc < pa { c } else { a }
}
