        let shift = bit + 1 - take;
        let mask = ((1usize << take) - 1) as c_uint;
        let chunk = (byte >> shift) & mask;

        result = (result << take) | chunk;
        remaining -= take;

        if shift == 0 {
            p = p.wrapping_add(1);
