                let hi = unsafe { *inp };
                // SAFETY: same as above, reading the low byte of the 16-bit sample is in bounds.
                let lo = unsafe { *inp.add(1) };
                let alpha = if key_defined
                    && (256 as c_uint)
                        .wrapping_mul(hi as c_uint)
                        .wrapping_add(lo as c_uint)
                        == key_r
                {
                    0 as c_uchar
