                // SAFETY: writing one RGBA pixel to valid output buffer.
                unsafe {
                    *out.add(0) = hi;
                    *out.add(1) = hi;
                    *out.add(2) = hi;
                    *out.add(3) = alpha;
                    inp = inp.add(2);
                    out = out.add(4);
